package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"

	"github.com/golang/avroparse"
)

// Define the Avro parser structure
type AvroParser struct {
	*avroparse.Parser
}

func (p *AvroParser) Parse() error {
	return p.ParseFile("main.go")
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run <script> <source_file_name> <struct_name>")
		os.Exit(1)
	}

	sourceFileName := os.Args[1]
	structName := os.Args[2]

	// Read the Go source code
	generatedCode, err := ioutil.ReadFile(sourceFileName)
	if err != nil {
		log.Fatalf("Failed to read source file: %v", err)
	}

	// Create a new instance of AvroParser
	p := &AvroParser{Parser: avroparse.NewParser(generatedCode)}

	// Parse the struct definition
	err = p.Parse()
	if err != nil {
		log.Fatalf("Error parsing struct definition: %v", err)
	}

	// Generate the Avro schema
	schemaBytes, err := json.MarshalIndent(p.Schema(), "", "    ")
	if err != nil {
		log.Fatalf("Error marshalling Avro schema: %v", err)
	}

	// Write the schema to a file
	err = ioutil.WriteFile(structName+".avsc", schemaBytes, 0644)
	if err != nil {
		log.Fatalf("Error writing Avro schema to file: %v", err)
	}

	fmt.Printf("Generated Avro schema for struct '%s' in file '%s'\n", structName, structName+".avsc")
}
```

